-- Same transfer, deadlock-free: lock both rows in id order first
BEGIN TRAN;
SELECT id FROM accounts WITH (UPDLOCK, ROWLOCK)
WHERE id IN (@a, @b) ORDER BY id;           -- PostgreSQL: ... ORDER BY id FOR UPDATE
UPDATE accounts SET balance -= @amt WHERE id = @from;
UPDATE accounts SET balance += @amt WHERE id = @to;
COMMIT;
